import (
	"container/heap"
	"math"
)

// Edge represents a directed edge to a neighbor with a given weight.
type Edge struct {
	To     int
	Weight int
}

// Graph is a weighted directed graph stored as an adjacency list.
// Nodes are identified by integer indices 0..N-1.
type Graph struct {
	Adj [][]Edge
}

// NewGraph creates a Graph with n nodes and no edges.
func NewGraph(n int) *Graph {
	return &Graph{Adj: make([][]Edge, n)}
}

// AddEdge adds a directed edge from u to v with the given weight.
// Weight must be non-negative; Dijkstra's algorithm does not support
// negative weights.
func (g *Graph) AddEdge(u, v, weight int) {
	g.Adj[u] = append(g.Adj[u], Edge{To: v, Weight: weight})
}

// Result holds the output of a Dijkstra run from a single source.
type Result struct {
	// Dist[v] is the shortest distance from the source to v.
	// math.MaxInt signals that v is unreachable.
	Dist []int

	// Prev[v] is the predecessor of v on the shortest path from the source.
	// -1 means v is the source itself or is unreachable.
	Prev []int
}

// ShortestPaths runs Dijkstra's algorithm from src and returns the
// shortest distances and predecessor map for every node in the graph.
//
// Time complexity:  O((V + E) log V) with a binary min-heap.
// Space complexity: O(V + E).
func (g *Graph) ShortestPaths(src int) Result {
	n := len(g.Adj)

	dist := make([]int, n)
	prev := make([]int, n)
	for i := range dist {
		dist[i] = math.MaxInt
		prev[i] = -1
	}
	dist[src] = 0

	pq := &minHeap{{node: src, dist: 0}}
	heap.Init(pq)

	for pq.Len() > 0 {
		curr := heap.Pop(pq).(item)

		// Skip stale entries — a shorter path was already settled.
		if curr.dist > dist[curr.node] {
			continue
		}

		for _, edge := range g.Adj[curr.node] {
			// Guard against overflow when dist[curr.node] is MaxInt.
			if dist[curr.node] == math.MaxInt {
				continue
			}

			newDist := dist[curr.node] + edge.Weight
			if newDist < dist[edge.To] {
				dist[edge.To] = newDist
				prev[edge.To] = curr.node
				heap.Push(pq, item{node: edge.To, dist: newDist})
			}
		}
	}

	return Result{Dist: dist, Prev: prev}
}

// Path reconstructs the shortest path from the source to dst using the
// predecessor map stored in Result. Returns nil if dst is unreachable.
func (r Result) Path(dst int) []int {
	if r.Dist[dst] == math.MaxInt {
		return nil // unreachable
	}

	// Walk backwards from dst to the source, then reverse.
	var path []int
	for node := dst; node != -1; node = r.Prev[node] {
		path = append(path, node)
	}

	// Reverse in-place.
	for l, rr := 0, len(path)-1; l < rr; l, rr = l+1, rr-1 {
		path[l], path[rr] = path[rr], path[l]
	}
	return path
}

// ---------------------------------------------------------------------------
// min-heap implementation (container/heap interface)
// ---------------------------------------------------------------------------

type item struct {
	node int
	dist int
}

type minHeap []item

func (h minHeap) Len() int            { return len(h) }
func (h minHeap) Less(i, j int) bool  { return h[i].dist < h[j].dist }
func (h minHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x interface{}) { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}
"}}
