---

## Structure

Two files: `dijkstra.go` (implementation) and `dijkstra_test.go` (tests).

**Public API:**
```go
g := dijkstra.NewGraph(6)
g.AddEdge(0, 1, 2)
g.AddEdge(0, 3, 6)
// ...

r := g.ShortestPaths(0)   // run from source node 0

fmt.Println(r.Dist[5])    // shortest distance to node 5
fmt.Println(r.Path(5))    // []int{0, 1, 3, 4, 5}
```

---

## How it works

**`ShortestPaths(src)`** — standard Dijkstra with a lazy-deletion min-heap:

1. Initialize all distances to `math.MaxInt`, set `dist[src] = 0`.
2. Push `(src, 0)` onto the min-heap.
3. Pop the minimum-distance item. If its recorded distance is stale (a shorter path was already settled), skip it.
4. Relax each outgoing edge. If a shorter path is found, update `dist` and `prev`, then push the new entry onto the heap.

The "lazy deletion" approach (pushing duplicates and skipping stale entries on pop) avoids the need for a decrease-key operation, which `container/heap` doesn't natively support. It's the standard Go idiom for Dijkstra.

**`Path(dst)`** — walks `prev[]` backwards from `dst` to the source, then reverses the slice. Returns `nil` for unreachable nodes.

---

## Complexity

| | |
|---|---|
| Time | O((V + E) log V) |
| Space | O(V + E) |

The heap can hold at most E entries (one per edge relaxation), so the log factor is bounded by log E ≤ log V².

---

## What the tests cover

- Basic shortest path and distance correctness
- Full distance array from a single source
- Path reconstruction for every node in a 5-node graph
- Unreachable nodes (`math.MaxInt` distance, `nil` path)
- Single-node graph (source = destination)
- Disconnected graph (two separate components)
- Parallel edges (cheaper one wins)
- Larger 6-node graph with multiple relaxation rounds

Here's a compact binary tree serializer using a pre-order traversal with a type-tagged node format.

## Format Design

Each node is encoded as:
- `1 byte` — tag: `0x01` = value node, `0x00` = null sentinel
- `4 bytes` — int value (only present when tag is `0x01`)

Null nodes cost 1 byte. Value nodes cost 5 bytes. No pointers stored anywhere.

```
[0x01][val:4B][left subtree][right subtree]   <- value node
[0x00]                                         <- null node
```

## Implementation

```c
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

/* ── Tree definition ─────────────────────────────────────────────────────── */

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

/* ── Buffer helpers ──────────────────────────────────────────────────────── */

/* Growable write buffer */
typedef struct {
    uint8_t *data;
    size_t   len;
    size_t   cap;
} WriteBuf;

/* Read cursor — never writes, never owns memory */
typedef struct {
    const uint8_t *data;
    size_t         len;   /* total bytes available  */
    size_t         pos;   /* current read position  */
} ReadBuf;

#define TAG_NULL  0x00
#define TAG_NODE  0x01

/* Returns 0 on success, -1 on allocation failure */
static int wb_push(WriteBuf *wb, const void *bytes, size_t n) {
    if (wb->len + n > wb->cap) {
        size_t new_cap = wb->cap ? wb->cap * 2 : 64;
        while (new_cap < wb->len + n) new_cap *= 2;
        uint8_t *p = realloc(wb->data, new_cap);
        if (!p) return -1;
        wb->data = p;
        wb->cap  = new_cap;
    }
    memcpy(wb->data + wb->len, bytes, n);
    wb->len += n;
    return 0;
}

/* Returns 0 on success, -1 if not enough bytes remain */
static int rb_read(ReadBuf *rb, void *out, size_t n) {
    if (rb->pos + n > rb->len) return -1;
    memcpy(out, rb->data + rb->pos, n);
    rb->pos += n;
    return 0;
}

/* ── Serialization ───────────────────────────────────────────────────────── */

/*
 * Serialize a binary tree into a compact byte buffer.
 *
 * On success: *out_buf points to a heap-allocated buffer of *out_len bytes.
 *             The caller is responsible for free()ing *out_buf.
 * On failure: returns -1, *out_buf is NULL, *out_len is 0.
 *
 * Encoding (pre-order, depth-first):
 *   null node  → [0x00]                  (1 byte)
 *   value node → [0x01][val LE 4 bytes]  (5 bytes) + left subtree + right subtree
 *
 * Values are stored in little-endian byte order so the format is
 * portable across host architectures.
 */
int tree_serialize(const TreeNode *root, uint8_t **out_buf, size_t *out_len) {
    *out_buf = NULL;
    *out_len = 0;

    WriteBuf wb = {0};

    /* Iterative pre-order using an explicit stack to avoid stack overflow
     * on deep/degenerate trees. */
    const TreeNode **stack = NULL;
    size_t stack_top = 0;
    size_t stack_cap = 0;

#define STACK_PUSH(node) do {                                           \
    if (stack_top == stack_cap) {                                       \
        size_t nc = stack_cap ? stack_cap * 2 : 32;                    \
        const TreeNode **p = realloc(stack, nc * sizeof(*stack));       \
        if (!p) { goto oom; }                                           \
        stack = p; stack_cap = nc;                                      \
    }                                                                   \
    stack[stack_top++] = (node);                                        \
} while (0)

    STACK_PUSH(root);

    while (stack_top > 0) {
        const TreeNode *node = stack[--stack_top];

        if (!node) {
            uint8_t tag = TAG_NULL;
            if (wb_push(&wb, &tag, 1) < 0) goto oom;
            continue;
        }

        /* Write tag + value (little-endian) */
        uint8_t tag = TAG_NODE;
        if (wb_push(&wb, &tag, 1) < 0) goto oom;

        uint32_t v;
        memcpy(&v, &node->val, sizeof(v)); /* reinterpret int bits */
        uint8_t le[4] = {
            (uint8_t)(v),
            (uint8_t)(v >> 8),
            (uint8_t)(v >> 16),
            (uint8_t)(v >> 24),
        };
        if (wb_push(&wb, le, 4) < 0) goto oom;

        /* Push right first so left is processed first (LIFO) */
        STACK_PUSH(node->right);
        STACK_PUSH(node->left);
    }

    free(stack);
    *out_buf = wb.data;
    *out_len = wb.len;
    return 0;

oom:
    free(stack);
    free(wb.data);
    return -1;

#undef STACK_PUSH
}

/* ── Deserialization ─────────────────────────────────────────────────────── */

/* Forward declaration for the recursive helper */
static TreeNode *deserialize_node(ReadBuf *rb);

/*
 * Deserialize a binary tree from a byte buffer produced by tree_serialize().
 *
 * Returns the root of the reconstructed tree, or NULL if the buffer is
 * empty, malformed, or a memory allocation fails.
 *
 * The caller is responsible for freeing the returned tree with tree_free().
 */
TreeNode *tree_deserialize(const uint8_t *buf, size_t len) {
    if (!buf || len == 0) return NULL;
    ReadBuf rb = { .data = buf, .len = len, .pos = 0 };
    return deserialize_node(&rb);
}

static TreeNode *deserialize_node(ReadBuf *rb) {
    uint8_t tag;
    if (rb_read(rb, &tag, 1) < 0) return NULL; /* truncated */

    if (tag == TAG_NULL) return NULL;
    if (tag != TAG_NODE) return NULL; /* corrupt tag byte */

    uint8_t le[4];
    if (rb_read(rb, le, 4) < 0) return NULL; /* truncated value */

    uint32_t v = (uint32_t)le[0]
               | ((uint32_t)le[1] << 8)
               | ((uint32_t)le[2] << 16)
               | ((uint32_t)le[3] << 24);

    TreeNode *node = malloc(sizeof(TreeNode));
    if (!node) return NULL;

    memcpy(&node->val, &v, sizeof(node->val)); /* restore int bits */
    node->left  = deserialize_node(rb);
    node->right = deserialize_node(rb);
    return node;
}

/* ── Utilities ───────────────────────────────────────────────────────────── */

TreeNode *tree_node(int val, TreeNode *left, TreeNode *right) {
    TreeNode *n = malloc(sizeof(TreeNode));
    assert(n);
    n->val = val; n->left = left; n->right = right;
    return n;
}

void tree_free(TreeNode *root) {
    if (!root) return;
    tree_free(root->left);
    tree_free(root->right);
    free(root);
}
```

## Tests

```c
#include <stdio.h>

/* Compare two trees structurally */
static int tree_equal(const TreeNode *a, const TreeNode *b) {
    if (!a && !b) return 1;
    if (!a || !b) return 0;
    return a->val == b->val
        && tree_equal(a->left,  b->left)
        && tree_equal(a->right, b->right);
}

static void print_result(const char *name, int pass) {
    printf("[%s] %s\n", pass ? "PASS" : "FAIL", name);
}

int main(void) {
    uint8_t *buf;
    size_t   len;
    TreeNode *got;
    int ok;

    /* ── Test 1: NULL tree ─────────────────────────────────────────────── */
    ok  = tree_serialize(NULL, &buf, &len);
    got = tree_deserialize(buf, len);
    print_result("null tree", ok == 0 && got == NULL);
    free(buf);

    /* ── Test 2: Single node ───────────────────────────────────────────── */
    TreeNode *single = tree_node(42, NULL, NULL);
    ok  = tree_serialize(single, &buf, &len);
    got = tree_deserialize(buf, len);
    print_result("single node", ok == 0 && tree_equal(single, got));
    /* expected size: 1 (node tag) + 4 (val) + 1 (left null) + 1 (right null) = 7 */
    print_result("single node size == 7", len == 7);
    free(buf); tree_free(got); tree_free(single);

    /* ── Test 3: Full balanced tree ────────────────────────────────────── */
    /*        1
