    TreeNode *full =
        tree_node(1,
            tree_node(2, tree_node(4,NULL,NULL), tree_node(5,NULL,NULL)),
            tree_node(3, tree_node(6,NULL,NULL), tree_node(7,NULL,NULL)));
    ok  = tree_serialize(full, &buf, &len);
    got = tree_deserialize(buf, len);
    print_result("full balanced tree", ok == 0 && tree_equal(full, got));
    /* 7 nodes × 5B + 8 null sentinels × 1B = 43 bytes */
    print_result("full tree size == 43", len == 43);
    free(buf); tree_free(got); tree_free(full);

    /* ── Test 4: Right-skewed (degenerate) tree ────────────────────────── */
    TreeNode *skewed = tree_node(1, NULL,
                         tree_node(2, NULL,
                           tree_node(3, NULL, NULL)));
    ok  = tree_serialize(skewed, &buf, &len);
    got = tree_deserialize(buf, len);
    print_result("right-skewed tree", ok == 0 && tree_equal(skewed, got));
    free(buf); tree_free(got); tree_free(skewed);

    /* ── Test 5: Negative and zero values ──────────────────────────────── */
    TreeNode *negvals = tree_node(0, tree_node(-1, NULL, NULL),
                                     tree_node(-2147483648, NULL, NULL));
    ok  = tree_serialize(negvals, &buf, &len);
    got = tree_deserialize(buf, len);
    print_result("negative/zero values", ok == 0 && tree_equal(negvals, got));
    free(buf); tree_free(got); tree_free(negvals);

    /* ── Test 6: Truncated buffer returns NULL ─────────────────────────── */
    TreeNode *simple = tree_node(99, NULL, NULL);
    tree_serialize(simple, &buf, &len);
    got = tree_deserialize(buf, 3); /* cut off mid-value */
