import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * A thread-safe LRU (Least Recently Used) cache with a fixed capacity.
 *
 * <p>Uses a doubly-linked list to maintain access order and a HashMap for O(1) lookups.
 * Concurrency is managed with a {@link ReentrantReadWriteLock}: reads acquire the read lock
 * and writes acquire the write lock.
 *
 * <p>Neither keys nor values may be null; {@link Optional} is used for the return type of
 * {@link #get} to make cache misses explicit.
 */
public class LRUCache<K, V> {

    private final int capacity;
    private final Map<K, Node<K, V>> map;
    private final Node<K, V> head; // sentinel: most-recently-used end
    private final Node<K, V> tail; // sentinel: least-recently-used end
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public LRUCache(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("Capacity must be positive");
        this.capacity = capacity;
        // Pre-size the map to avoid rehashing up to the expected load.
        this.map = new HashMap<>((int) Math.ceil(capacity / 0.75) + 1);
        this.head = new Node<>(null, null);
        this.tail = new Node<>(null, null);
        head.next = tail;
        tail.prev = head;
    }

    /**
     * Returns the value associated with {@code key}, or {@link Optional#empty()} on a miss.
     * On a hit, the entry is promoted to the most-recently-used position.
     *
     * <p>Locking: acquires the read lock first to check for the key. On a hit, releases the
     * read lock and acquires the write lock to reorder the list. A re-check after acquiring
     * the write lock guards against eviction in the window between the two lock acquisitions.
     * Note that the "parallel reads" benefit of the read lock is limited to cache misses;
     * a read-heavy workload with a high hit rate will still serialize on the write lock.
     */
    public Optional<V> get(K key) {
        if (key == null) throw new NullPointerException("key must not be null");

        lock.readLock().lock();
        try {
            if (!map.containsKey(key)) {
                return Optional.empty(); // miss: no write needed, read lock is sufficient
            }
        } finally {
            lock.readLock().unlock();
        }

        // Hit path: must reorder the list, so upgrade to write lock.
        // There is a window between releasing the read lock and acquiring the write lock
        // during which another thread may evict or move this node. The re-check below
        // handles both cases:
        //   - Eviction: containsKey returns false → we return empty, avoiding a use-after-eviction.
        //   - Moved by another write: the node is still in the list; unlink + addToFront is
        //     idempotent for a live node, so moveToFront remains correct.
        lock.writeLock().lock();
        try {
            Node<K, V> node = map.get(key);
            if (node == null) {
                return Optional.empty(); // evicted between the two lock acquisitions
            }
            moveToFront(node);
            return Optional.of(node.value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    /**
     * Associates {@code key} with {@code value}, evicting the least-recently-used entry if
     * the cache is at capacity. If {@code key} is already present, its value is updated and
     * it is promoted to most-recently-used.
     */
    public void put(K key, V value) {
        if (key == null) throw new NullPointerException("key must not be null");
        if (value == null) throw new NullPointerException("value must not be null");

        lock.writeLock().lock();
        try {
            Node<K, V> node = map.get(key);
            if (node != null) {
                node.value = value;
                moveToFront(node);
            } else {
                if (map.size() >= capacity) {
                    Node<K, V> lru = tail.prev;
                    unlink(lru);
                    map.remove(lru.key);
                }
                Node<K, V> newNode = new Node<>(key, value);
                map.put(key, newNode);
                addToFront(newNode);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    /** Returns the number of entries currently in the cache. */
    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    private void moveToFront(Node<K, V> node) {
        unlink(node);
        addToFront(node);
    }

    private void unlink(Node<K, V> node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void addToFront(Node<K, V> node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> prev;
        Node<K, V> next;

        Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }
}
